Fixpoint effok (t : eff) : Prop :=
  match t with
  | EDone c => cok c
  | EIllegal _ | EDefinedIllegal _ | EEcall _ | EEbreak _ | EFault _ => True
  | ELoad n a k => forall v, effok (k v)
  | EStore n a v k => effok k
  end.
